-- users/set-role
-- Changes a user's role. Only the `migrator` database role may write this column (migration 0005),
-- so this runs from `pnpm users:role` on the server, never from the website.
--
-- Parameters, with the example values used to render this file:
--   $1 = "reviewer"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/users.ts. Do not edit by hand.

update "users"
set "role" = $1, "updated_at" = now()
where "users"."id" = $2
returning "id";
